	--callout-bg-stamp-size: 50px auto;
	--callout-bg-stamp-position: 97% 92%;


    /*
    ##############################################################
    ##############################################################
    # 
    # images
    #
    ##############################################################
    ##############################################################
    */

	/* image from wikiimages on pixabay */
	--stars1-image: url('data:image/png;base64,');
	/* image from Kranich17 on pixabay */
	--rainy2-image: url("data:image/jpeg;base64,");
	--rainy1-image: url("data:image/jpeg;base64,");

    /*
    ##############################################################
    ##############################################################
    # 
    # Variables
    #
    ##############################################################
    ##############################################################
    */
	/*				hue													sat								lum		  */
	--whim-color: 	hsl(var(--accent-h), 								var(--accent-s), 				var(--accent-l));
	--dark-whim: 	hsl(calc(var(--accent-h)), 							40%, 							var(--dark-whim-lum));
	--light-whim: 	hsl(calc(var(--accent-h)), 							40%, 							var(--light-whim-lum));
	--dw: 		hsl(calc(var(--accent-h) + var(--weakest-shift-hue)), 	calc(var(--accent-s) - 40%), 	var(--dw-lum));
	--mw: 		hsl(calc(var(--accent-h) + 5), 							40%, 							var(--mw-lum));
	--lw: 		hsl(calc(var(--accent-h) - 0), 							calc(var(--accent-s) - 20%), 	var(--lw-lum));
	--con:		hsl(calc(var(--accent-h) + var(--shift-hue)),			calc(var(--accent-s) - 10%), 	var(--con-lum));
	--lcon:		hsl(calc(var(--accent-h) + var(--weak-shift-hue)), 		70%, 							var(--lcon-lum));
	--bcon:		hsl(calc(var(--accent-h) + var(--weak-shift-hue)), 		30%, 							var(--bcon-lum));
	--dcon:		hsl(calc(var(--accent-h) + var(--shift-hue)),			calc(var(--accent-s) - 10%), 	var(--dcon-lum));
	--mcon: 	hsl(calc(var(--accent-h) + var(--shift-hue)), 			20%, 							var(--mcon-lum));
	--mdcon: 	hsl(calc(var(--accent-h) - var(--weak-shift-hue)), 		30%, 							var(--mdcon-lum));

	--nbg-size: 100% 100%;
	--nbg-attachment: fixed;
	--nbg-anim-speed: 100s;
	--nbg-position: 0% 0%;

	--nbg-gradient-transparency: 80%;
	--nbg-gradient-size: 200% 200%;
	--nbg-linear-rota: -45deg;
	--nbg-linear-color1: color-mix(in srgb, var(--color-red), transparent var(--nbg-gradient-transparency));
	--nbg-linear-color2: color-mix(in srgb, var(--color-orange), transparent var(--nbg-gradient-transparency));
	--nbg-linear-color3: color-mix(in srgb, var(--color-yellow), transparent var(--nbg-gradient-transparency));
	--nbg-linear-color4: color-mix(in srgb, var(--color-green), transparent var(--nbg-gradient-transparency));
	--nbg-linear-color5: color-mix(in srgb, var(--color-cyan), transparent var(--nbg-gradient-transparency));
	--nbg-linear-color6: color-mix(in srgb, var(--color-blue), transparent var(--nbg-gradient-transparency));
	--nbg-linear-color7: color-mix(in srgb, var(--color-purple), transparent var(--nbg-gradient-transparency));
	--nbg-linear-color8: color-mix(in srgb, var(--color-pink), transparent var(--nbg-gradient-transparency));
	
	--nbg-reprad-shape: circle;
	--nbg-reprad-color2: var(--nbg-solid-color);
	--nbg-reprad-sizes1: 0px 3px;
	--nbg-reprad-sizes2: 3px 15px;
	--nbg-reprad-box-percents: 0% 0%;
	--nbg-reprad-box-sizes: 150px 100px;
	--nbg-reprad-box-repeat: repeat;
	--nbg-lines-rota: 90deg;
	--nbg-lines-spacing: 30px;
	--nbg-lines-spacing-and-width: 33px;
	--nbg-lines-color1: var(--nbg-solid-color);

	--nbg-whim-reprad: 
		repeating-radial-gradient(
			var(--nbg-reprad-shape),
			color-mix(in srgb, var(--nbg-draw-color), var(--nbg-solid-color) var(--nbg-reprad-transparency1)) var(--nbg-reprad-sizes1),
			color-mix(in srgb, var(--nbg-draw-color), var(--nbg-solid-color) var(--nbg-reprad-transparency2)) var(--nbg-reprad-sizes2)
		)
		content-box border-box var(--nbg-reprad-box-percents) / var(--nbg-reprad-box-sizes) var(--nbg-reprad-box-repeat);
	--nbg-rainbow-linear:
		linear-gradient(
			var(--nbg-linear-rota), 
			var(--nbg-linear-color1), 
			var(--nbg-linear-color2), 
			var(--nbg-linear-color3), 
			var(--nbg-linear-color4),
			var(--nbg-linear-color5),
			var(--nbg-linear-color6),
			var(--nbg-linear-color7),
			var(--nbg-linear-color8)
		);
	--nbg-whim-linear:
		linear-gradient(
			-45deg, 
			var(--bgw1), 
			var(--bgw2), 
			var(--bgw3), 
			var(--bgw4),
			var(--bgw5)
		);
	--nbg-whim-linear-alt:
		linear-gradient(
			-45deg, 
			var(--bgw1a), 
			var(--bgw2a), 
			var(--bgw3a), 
			var(--bgw4a),
			var(--bgw5a)
		);
	--nbg-whim-linear-rainbow:
		linear-gradient(
			-45deg, 
			var(--color-red), 
			var(--color-yellow), 
			var(--color-cyan), 
			var(--color-blue),
			var(--color-purple)
		);
	--nbg-whim-lines:
        repeating-linear-gradient(
            var(--nbg-lines-rota), var(--nbg-lines-color1), var(--nbg-lines-color1) var(--nbg-lines-spacing), 
            color-mix(in srgb, var(--nbg-lines-color2), transparent var(--nbg-lines-transparency1)) var(--nbg-lines-spacing), 
            color-mix(in srgb, var(--nbg-lines-color2), transparent var(--nbg-lines-transparency2)) var(--nbg-lines-spacing-and-width)
        );

	--scan-spacing: 2px;
	--scan-spacing-and-width: 3px;
	
	--mask-spacing: 2px;
	--mask-spacing-and-width: 3px;
	--nbg-whim-scanlines: 
        repeating-linear-gradient(
            0deg, var(--scan-color1), var(--scan-color1) var(--scan-spacing), 
            var(--scan-color2) var(--scan-spacing), 
            var(--scan-color2) var(--scan-spacing-and-width)
        );
	--nmask-whim-scanlines: 
        repeating-linear-gradient(
            0deg, var(--mask-color1), var(--mask-color1) var(--mask-spacing), 
            var(--mask-color2) var(--mask-spacing), 
            var(--mask-color2) var(--mask-spacing-and-width)
        );

	--emphasis-text: hsl(
		calc(var(--accent-h) - var(--shift-hue)),
		var(--styled-text-sat),
		var(--styled-text-lum)
	);
	--strong-text: hsl(
		calc(var(--accent-h) + var(--shift-hue)),
		var(--styled-text-sat),
		var(--styled-text-lum)
	);
	--strike-text: hsl(
		calc(var(--accent-h) + var(--strongest-shift-hue)),
		var(--styled-text-sat),
		var(--styled-text-lum)
	);
	
	--hfont: 'Faculty_Glyphic';
	--h1-font: var(--hfont);
	--h2-font: var(--hfont);
	--h3-font: var(--hfont);
	--h4-font: var(--hfont);
	--h5-font: var(--hfont);
	--h6-font: var(--hfont);
	--h1-size: 2em;
	--h2-size: 1.9em;
	--h3-size: 1.8em;
	--h4-size: 1.7em;
	--h5-size: 1.6em;
	--h6-size: 1.5em;
	--h1-weight: 200;
	--h2-weight: 200;
	--h3-weight: 200;
	--h4-weight: 200;
	--h5-weight: 200;
	--h6-weight: 200;

	--scrollbar-width: 15px;

	--tab-curve: 1px;
	--tab-radius: 1px;
	--tab-radius-active: 1px;

	--embed-border-start: 0px;

	--bases-table-border-thickness: 0px;

	--tag-color: var(--bcon);

	--secrets-color:  color-mix(in srgb, transparent, #181818 50%);

	/* Used by snippets and settings */
	--bg-color: color-mix(in srgb, transparent, var(--nbg-solid-color) 20%);
	--bg-more-color: color-mix(in srgb, transparent, var(--nbg-solid-color) 80%);
}


.theme-dark {

	--dark-whim-lum: 6%;
	--light-whim-lum: 90%;
	--dw-lum: 10%;
	--mw-lum: 65%;
	--lw-lum: 80%;
	--con-lum: 80%;
	--lcon-lum: 95%;
	--bcon-lum: 60%;
	--dcon-lum: 50%;
	--mcon-lum: 15%;
	--mdcon-lum: 12%;

	--callout-lum: white;
	--glow-color1: var(--lw);
	--glow-color2: var(--light-whim);
	--glow-transparency: 90%;
	--shadow-color: var(--dark-whim);

	--hr-color: white;

	--whim-strength: 15%;
	--color-red: color-mix(in srgb, #ce3c3c, var(--whim-color) var(--whim-strength));
	--color-orange: color-mix(in srgb, #d46f34, var(--whim-color) var(--whim-strength));
	--color-yellow: color-mix(in srgb, #e9af53, var(--whim-color) var(--whim-strength));
