/*
##############################################################
##############################################################
# 
# Obsidian-override-y Stuff
#
##############################################################
##############################################################
*/


.theme-light .workspace {
    background-color: transparent;
	background: var(--nbg-whim-reprad);
} 
.theme-dark .workspace {
    background-color: transparent;
	background: var(--nbg-whim-reprad);
}
.horizontal-main-container {
    background: var(--nbg-whim-linear);
    background-attachment: fixed;
    background-size: 200% 200%;
}
.workspace-split.mod-root {
    background-color: var(--background-primary);
}

.workspace-leaf-content,
.workspace-tab-header-container {
	background-color: transparent;
}

body {
    --background-primary: transparent;
    --background-secondary: transparent;
    --divider-width: 0px;
}

.menu, .model-header, .modal-content, .suggestion-container, .modal {
	background-color: color-mix(in srgb, var(--dw), transparent 10%);
    backdrop-filter: brightness(0.65) blur(3px);
}

/* .view-header {
	border-style: solid;
	border-color: color-mix(in srgb, var(--dw), transparent 0%);
	border-width: 0px 1px 1px 1px;
} */

.prompt, .mobile-tab-switcher, .graph-controls, .bases-cards-item, .bases-header, .status-bar {
	background-color: color-mix(in srgb, var(--dw), transparent 15%);
    backdrop-filter: brightness(0.65) blur(3px);
}

.embed-title {
	color: transparent;
}

.empty-state {
	/* background-color: color-mix(in srgb, var(--dark-whim), transparent 80%); */
	background: 
		radial-gradient(circle, color-mix(in srgb, var(--glow-color1), transparent var(--glow-transparency)), transparent 50%),
		radial-gradient(circle, color-mix(in srgb, var(--glow-color1), transparent var(--glow-transparency)), transparent 30%),
		radial-gradient(circle, color-mix(in srgb, var(--glow-color1), transparent var(--glow-transparency)), transparent 20%);
	border-radius: 25px;
	/* box-shadow: inset 0px 0px 100px 100px color-mix(in srgb, var(--dark-whim), transparent 90%); */
}
.empty-state-action {
	color: var(--lw);
}

.bases-table-container {
	background-color: color-mix(in srgb, var(--dark-whim), transparent 50%);
	border-radius: 10px;
}
.bases-header {
	background-color: color-mix(in srgb, var(--dark-whim), transparent 50%);
	border-radius: 15px;
}
.bases-table-cell {
	border: white;
}

.metadata-container {
	box-shadow: 0px 0px 2px 4px color-mix(in srgb, black, transparent 95%);
    backdrop-filter: blur(5px);
	border-width: 1px;
	border-radius: 2px;
}
.workspace-leaf-content[data-mode="preview"]
.markdown-preview-view.hide_properties_in_read_mode
.metadata-container{
    display: none;
}
.metadata-add-button {
    display: none;
}




/* Text and image styles */

.cm-em, .el-p em {
	color: var(--emphasis-text);
}

.cm-strong, .el-p strong {
	color: var(--strong-text);
}

.cm-strikethrough, .el-p strikethrough {
	color: var(--strike-text);
}

img {
	opacity: 0.5;
}

img:hover {
	opacity: 1.0;
}

.cm-active.cm-line {
	background-color: color-mix(in srgb, var(--bcon), transparent 95%);
}
.cm-focused .inline-title {
	color: color-mix(in srgb, var(--con), white 50%);
}
.cm-focused .cm-active.cm-line {
	background-color: color-mix(in srgb, var(--bcon), transparent 80%);
}

