}


body .markdown-rendered hr,
body .markdown-source-view hr {
	background-color: color-mix(in srgb, var(--hr-color), transparent 0%);
	height: var(--hr-size);
	-webkit-mask-image: var(--hr-svg);
	-webkit-mask-position: center center;
	-webkit-mask-repeat: var(--hr-repeat);
	-webkit-mask-size: contain;
	opacity: var(--hr-opacity);
}




/*
##############################################################
##############################################################
