/* Misc/UI */

.whim-fullwidth {
	--file-line-width: 100%;
}
.whim-notitle .inline-title {
	display: none;
}
.whim-noreadproperties {
    --metadata-display-reading: none;
}
.whim-noeditproperties {
	--metadata-display-editing: none;
}
.whim-ui-smaller-checkboxes {
	--checkbox-size: 20px;
}
.whim-unwhim-images img {
	opacity: 1;
}
.whim-narrow {
	max-width: 800px;
}
body.whim-ui-no-active-line .cm-active.cm-line,
.whim-ui-no-active-line .cm-active.cm-line {
	background-color: transparent;
}
body.whim-ui-no-active-note-title-bright .cm-focused .inline-title,
.whim-ui-no-active-note-title-bright .cm-focused .inline-title {
	color: var(--h1-color);
}

body.whim-ui-secrets .workspace,
.whim-ui-secrets {
	background-color: black;
}
body.whim-ui-secrets:not(cm-active),
.whim-ui-secrets:not(cm-active) {
	color: var(--secrets-color);
	--text-normal: var(--secrets-color);
	--code-normal: var(--secrets-color);
	--tag-color: var(--secrets-color);
	--checklist-done-color: var(--secrets-color);
	--emphasis-text: var(--secrets-color);
	--strong-text: var(--secrets-color);
	--strike-text: var(--secrets-color); 
	--h1-color: var(--secrets-color); 
	--h2-color: var(--secrets-color); 
	--h3-color: var(--secrets-color); 
	--h4-color: var(--secrets-color); 
	--h5-color: var(--secrets-color); 
	--h6-color: var(--secrets-color); 
	--link-color: var(--secrets-color); 
	--link-external-color: var(--secrets-color); 
	--text-highlight-bg: black;
}
.whim-ui-secrets .callout {
	background-color: black;
	color: var(--secrets-color);
	border-color: var(--secrets-color);
}
.whim-ui-secrets .callout-title-inner {
	color: var(--secrets-color);
	border-color: var(--secrets-color);
}
body.whim-ui-secrets .cm-active,
.whim-ui-secrets .cm-active {
	--emphasis-text: hsl(
		calc(var(--accent-h) - var(--shift-hue)),
		var(--styled-text-sat),
		var(--styled-text-lum)
	);
	--strong-text: hsl(
		calc(var(--accent-h) + var(--shift-hue)),
		var(--styled-text-sat),
		var(--styled-text-lum)
	);
	--strike-text: hsl(
		calc(var(--accent-h) + var(--strongest-shift-hue)),
		var(--styled-text-sat),
		var(--styled-text-lum)
	);
	color: var(--light-whim);
	--text-normal: var(--light-whim);
	--code-normal: var(--light-whim);
	--tag-color: var(--bcon);
	--checklist-done-color: var(--light-whim);
}

