/* Classes for Style Settings only */
/* If you update something here, update the corresponding snippet as well. */

body.whim-hue-shift-alt, .theme-dark.whim-hue-shift-alt, .theme-light.whim-hue-shift-alt {
	--weakest-shift-hue: 20;
	--weakest-shift-hue-deg: 20deg;
	--weak-shift-hue: 50;
	--weak-shift-hue-deg: 50deg;
	--shift-hue: 100;
	--shift-hue-deg: 100deg;
	--strong-shift-hue: 150;
	--strong-shift-hue-deg: 150deg;
	--strongest-shift-hue: 200;
	--strongest-shift-hue-deg: 200deg;
}
body.whim-hue-shift-less, .theme-dark.whim-hue-shift-less, .theme-light.whim-hue-shift-less {
	--weakest-shift-hue: -10;
	--weakest-shift-hue-deg: -10deg;
	--weak-shift-hue: -20;
	--weak-shift-hue-deg: -20deg;
	--shift-hue: -30;
	--shift-hue-deg: -30deg;
	--strong-shift-hue: -50;
	--strong-shift-hue-deg: -50deg;
	--strongest-shift-hue: -70;
	--strongest-shift-hue-deg: -70deg;
}

/* These don't have a snippet, because the snippets that might use it do something like it automatically. */

body.whim-emboss-abstract-app .workspace,
body.whim-emboss-compass-app .workspace,
body.whim-emboss-hand-app .workspace,
body.whim-emboss-flowers-app .workspace,
body.whim-emboss-crying-app .workspace,
body.whim-emboss-dots-app .workspace,
body.whim-emboss-halftone-app .workspace,
body.whim-emboss-artnouveau12-app .workspace,
body.whim-emboss-castle-app .workspace,
body.whim-emboss-space-app .workspace,
body.whim-emboss-corner-app .workspace,
body.whim-emboss-border-app .workspace,
body.whim-emboss-seamless2-app .workspace,
body.whim-emboss-seamless1-app .workspace,
body.whim-emboss-perspective-app .workspace,
body.whim-emboss-heron-app .workspace,
body.whim-emboss-woman3-app .workspace,
body.whim-emboss-artnouveau2-app .workspace,
body.whim-emboss-woman1-app .workspace {
	--ribbon-background: var(--bg-color);
	--ribbon-background-collapsed: var(--bg-color);
	background-color: var(--bg-more-color);
}

body.whim-body-bg-color-override .workspace {
	--ribbon-background: var(--bg-color);
	--ribbon-background-collapsed: var(--bg-color);
}
body.whim-body-bg-color-override .workspace-leaf-content,
body.whim-body-bg-color-override .workspace-tab-header-container {
	background-color: var(--bg-color);
}

body.whim-body-bg-color-more-override .workspace {
	--ribbon-background: var(--bg-more-color);
	--ribbon-background-collapsed: var(--bg-more-color);
}
body.whim-body-bg-color-more-override .workspace-leaf-content,
body.whim-body-bg-color-more-override .workspace-tab-header-container {
	background-color: var(--bg-more-color);
}


body.whim-bg-filter-blur .workspace {
    backdrop-filter: brightness(0.8) blur(4px);
}
body.whim-bg-filter-lighter .workspace {
    backdrop-filter: brightness(1.3);
}
body.whim-bg-filter-darker .workspace {
    backdrop-filter: brightness(0.4);
}
body.whim-bg-filter-blur-lighter .workspace {
    backdrop-filter: brightness(1.3) blur(4px);
}
body.whim-bg-filter-blur-darker .workspace {
    backdrop-filter: brightness(0.4) blur(4px);
}
body.whim-bg-filter-grayscale .workspace {
    backdrop-filter: grayscale(1);
}
body.whim-bg-filter-blur-grayscale .workspace {
    backdrop-filter: brightness(0.8) blur(4px) grayscale(1);
}

body.whim-bg-gradient-rainbow .horizontal-main-container {
    background: var(--nbg-whim-linear-rainbow);
    background-attachment: fixed;
    background-size: 400% 400%;
}
body.whim-bg-gradient-stronger .horizontal-main-container {
    background: var(--nbg-whim-linear-alt);
    background-attachment: fixed;
    background-size: 400% 400%;
}

body.whim-bg-layer1-animate-faster .horizontal-main-container {
    animation: gradient 60s ease infinite;
}
body.whim-bg-layer1-animate-basic .horizontal-main-container {
    animation: gradient 120s ease infinite;
}
body.whim-bg-layer1-animate-slower .horizontal-main-container {
    animation: gradient 240s ease infinite;
}
body.whim-bg-layer1-animate-slowest .horizontal-main-container {
    animation: gradient 480s ease infinite;
}


body.whim-bg-layer1-center .horizontal-main-container {
	background-position: 50% 50%;
}
body.whim-bg-layer1-bigger .horizontal-main-container {
	background-size: 300%;
	background-position: 50% 50%;
}
body.whim-bg-layer1-biggest .horizontal-main-container {
	background-size: 400%;
	background-position: 50% 50%;
}

body.whim-ui-dude-wheres-my-scrollbar {
	--scrollbar-thumb-bg: color-mix(in srgb, var(--whim-color), transparent 75%);
}
body.whim-ui-more-dividers {
	--divider-color: color-mix(in srgb, var(--whim-color), transparent 75%);
    --divider-width: 2px;
}
body.whim-ui-fewer-dividers {
	--tab-outline-color: transparent;
}

